from string import ascii_uppercase

def task_func(dict1):
    ids = []
    used = set()

    def employee_count(value):
        if isinstance(value, bool):
            return 1
        if isinstance(value, int):
            return value
        try:
            return len(value)
        except TypeError:
            try:
                return sum(1 for _ in value)
            except TypeError:
                return 1

