import urllib.parse
import requests
import json

def task_func(myString, API_KEY):
    def extract_urls(text):
        if not text:
            return []
        pattern = re.compile(
            r'(?i)\b((?:https?://|ftp://|www\.)[^\s<>"\'\)\]]+|(?:[a-z0-9-]+\.)+[a-z]{2,}(?:/[^\s<>"\'\)\]]*)?)'
        )
        candidates = pattern.findall(text)
        cleaned = []
        for u in candidates:
            u = u.strip().rstrip('.,;:!?)]}>\'"')
            if u:
                cleaned.append(u)
        return cleaned

    def extract_domain(url):
        if not url:
            return None
        parsed_input = url if re.match(r'^[a-z][a-z0-9+.-]*://', url, re.I) else '//' + url
        parsed = urllib.parse.urlparse(parsed_input)
        host = parsed.hostname or parsed.netloc or parsed.path
        if not host:
            return None
        return host.lower()

    def lookup_domain(domain):
        try:
            if API_KEY:
                api_url = f"https://pro.ip-api.com/json/{urllib.parse.quote(domain)}?key={urllib.parse.quote(str(API_KEY))}"
            else:
                api_url = f"https://ip-api.com/json/{urllib.parse.quote(domain)}"
            response = requests.get(api_url, timeout=10, headers={"User-Agent": "Mozilla/5.0"})
            response.raise_for_status()
            return response.json()
        except (requests.RequestException, ValueError, json.JSONDecodeError):
            return None

    result = {}
    seen = set()

    for url in extract_urls(myString):
        domain = extract_domain(url)
        if not domain or domain in seen:
            continue
        seen.add(domain)
        result[domain] = lookup_domain(domain)

    return result

