import os
import json
from collections import Counter

def task_func(json_files_path='./json_files/', key='name'):
    """
    Count occurrences of values associated with a specified key across all JSON files
    in the given directory.

    Args:
        json_files_path (str): Path to a directory containing JSON files.
        key (str): The key whose values should be counted.

    Returns:
        dict: A dictionary mapping each encountered value of `key` to its count.
    """
    def _make_hashable(value):
        try:
            hash(value)
            return value
        except TypeError:
            return json.dumps(value, sort_keys=True, ensure_ascii=False)

    def _collect_values(obj, target_key):
        collected = []
        if isinstance(obj, dict):
            for k, v in obj.items():
                if k == target_key:
                    collected.append(_make_hashable(v))
                collected.extend(_collect_values(v, target_key))
        elif isinstance(obj, list):
            for item in obj:
                collected.extend(_collect_values(item, target_key))
        return collected

    counts = Counter()

    if not os.path.isdir(json_files_path):
        return {}

    for filename in os.listdir(json_files_path):
        if not filename.lower().endswith('.json'):
            continue

        file_path = os.path.join(json_files_path, filename)
        if not os.path.isfile(file_path):
            continue

        try:
            with open(file_path, 'r', encoding='utf-8') as f:
                data = json.load(f)
        except (OSError, json.JSONDecodeError):
            continue

        counts.update(_collect_values(data, key))

    return dict(counts)

