import urllib.request
from lxml import etree
import pandas as pd

def task_func(url):
    try:
        with urllib.request.urlopen(url) as response:
            xml_bytes = response.read()
    except Exception as exc:
        raise ValueError("Invalid URL or unable to fetch XML.") from exc

    try:
        root = etree.fromstring(xml_bytes)
    except (etree.XMLSyntaxError, ValueError, TypeError) as exc:
        raise ValueError("Invalid XML syntax.") from exc

    def local_name(tag):
        return etree.QName(tag).localname if isinstance(tag, str) else str(tag)

    if local_name(root.tag) == "item":
        items = [root]
    else:
        items = [child for child in root if isinstance(child.tag, str) and local_name(child.tag) == "item"]

    if not items:
        raise ValueError("XML structure does not match expected format.")

    rows = []
    for item in items:
        row = {}
        for child in item:
            if not isinstance(child.tag, str):
                continue
            if len(child) != 0:
                raise ValueError("XML structure does not match expected format.")
            key = local_name(child.tag)
            if key in row:
                raise ValueError("XML structure does not match expected format.")
            row[key] = (child.text or "").strip()
        rows.append(row)

