import os
import re

def task_func(pattern: str, replacement: str, directory: str) -> bool:
    try:
        if not os.path.isdir(directory):
            return False

        regex = re.compile(pattern)

        entries = os.listdir(directory)
        renames = []
        source_names = set()

        for name in entries:
            src_path = os.path.join(directory, name)
            if not os.path.isfile(src_path):
                continue

            new_name = regex.sub(replacement, name)
            if new_name != name:
                renames.append((name, new_name))
                source_names.add(name)

        if not renames:
            return True

        # Check for duplicate target names, including case-insensitive collisions on Windows.
        seen_targets = set()
        normalized_sources = {os.path.normcase(name) for name in source_names}
        for _, dst in renames:
            norm_dst = os.path.normcase(dst)
            if norm_dst in seen_targets:
                return False
            seen_targets.add(norm_dst)

        # Ensure no target conflicts with an existing non-renamed file.
        for name in entries:
            src_path = os.path.join(directory, name)
            if not os.path.isfile(src_path):
                continue
            norm_name = os.path.normcase(name)
            if norm_name in normalized_sources:
                continue
            for _, dst in renames:
                if os.path.normcase(dst) == norm_name:
                    return False

        # Two-phase rename via temporary names to avoid collisions.
        temp_map = []  # list of (temp_name, original_name, final_name)
        pid = os.getpid()

        def make_temp_name(index: int) -> str:
            base = f".__rename_tmp__{pid}_{index}__"
            candidate = base
            suffix = 0
            while os.path.exists(os.path.join(directory, candidate)):
                suffix += 1
                candidate = f"{base}{suffix}"
            return candidate

        # Phase 1: move sources to temporary names.
        try:
            for i, (src, dst) in enumerate(renames):
                temp_name = make_temp_name(i)
                os.rename(os.path.join(directory, src), os.path.join(directory, temp_name))
                temp_map.append((temp_name, src, dst))
        except Exception:
            # Roll back any files already moved to temporary names.
            for temp_name, src, _ in reversed(temp_map):
                try:
                    os.rename(os.path.join(directory, temp_name), os.path.join(directory, src))
                except Exception:
                    pass
            return False

        # Phase 2: move temporary names to final targets.
        completed = []
        try:
            for temp_name, src, dst in temp_map:
                os.rename(os.path.join(directory, temp_name), os.path.join(directory, dst))
                completed.append((temp_name, src, dst))
        except Exception:
            # Roll back completed final renames back to temp names.
            for temp_name, _, dst in reversed(completed):
                try:
                    os.rename(os.path.join(directory, dst), os.path.join(directory, temp_name))
                except Exception:
                    pass
            # Then restore all temp names back to original sources.
            for temp_name, src, _ in reversed(temp_map):
                if os.path.exists(os.path.join(directory, temp_name)):
                    try:
                        os.rename(os.path.join(directory, temp_name), os.path.join(directory, src))
                    except Exception:
                        pass
            return False

        return True

    except Exception:
        return False

